INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('059487f6-5b70-49ef-8598-c2dd8088247e', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$1. óra: Az év bevezetése, ismétlés, játékos bevezető$q$, $q$Éves munkarend, elvárások, játékos feladatok az éves munka elkezdéséhez.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év eleji ismétlés, diagnosztika$q$, $q$[{"id": "56d889d3-73ec-48c1-a2e3-f6814bd42891", "text": "Mi az éves matematika munka legfőbb célja?", "type": "multiple-choice", "options": [{"id": "6bd797d3-1cb9-4272-ae01-2d736078ff9c", "text": "A gondolkodási képesség és matematikai tudás fejlesztése", "isCorrect": true}, {"id": "4a1a2383-0718-4ed0-8900-45251b4e53ca", "text": "A könyvek visszagyűjtése", "isCorrect": false}, {"id": "6b6022bf-b981-4139-8fe7-c7a77fe35f90", "text": "Csak a házi feladat írása", "isCorrect": false}, {"id": "b9e16d0d-e095-4e73-a567-88633ded5e8e", "text": "A számonkérések elkerülése", "isCorrect": false}], "timeLimit": 15}, {"id": "29b0b42d-9c04-4ffa-8912-b6b660cf2185", "text": "A játékos matematikai feladatok segítik a tanulásra való ráhangolódást.", "type": "true-false", "options": [{"id": "70b28ac2-091d-420f-91ee-aff0fce980aa", "text": "Igaz", "isCorrect": true}, {"id": "2783c93a-831b-41aa-9f16-9b33abecc3aa", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "121c40dd-5abc-4506-b333-3c3f50bbdb04", "text": "Hány hétből áll egy átlagos magyar tanév?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "62edd831-98e5-4bdd-8535-2dae4631d786", "text": "Melyik állítás ír le helyes tanulási magatartást?", "type": "multiple-choice", "options": [{"id": "58a76fac-20db-4ec8-bc86-ed654efad126", "text": "Rendszeres felkészülés és a hibák megbeszélése", "isCorrect": true}, {"id": "e4e7bd0c-52e5-48f6-8d83-78d83e07cf20", "text": "Minden feladat feladása az első hibánál", "isCorrect": false}, {"id": "ec5cca43-7f84-4cce-98c3-9c561a0df15e", "text": "A füzet otthon hagyása", "isCorrect": false}, {"id": "171d9b6d-df46-45c1-bd4f-220de9a60317", "text": "Másolás a padtárstól", "isCorrect": false}], "timeLimit": 15}, {"id": "094b0c47-2179-4864-86d6-af551a6fa240", "text": "Mennyi a 25 + 75 összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "f9d87b6c-c59c-485f-a544-9ebe8e6c4000", "text": "A matematikai órákon a csoportmunka során fontos a kooperáció és egymás segítése.", "type": "true-false", "options": [{"id": "6d199829-32a3-4923-8bca-ca39324fc416", "text": "Igaz", "isCorrect": true}, {"id": "b7186caa-f419-41d9-848e-c9f98ac27120", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "c601deb2-30ae-4592-96a4-1ecab1d60d7f", "text": "Mennyi 8 * 9?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('71e75bc6-52cd-4398-90db-93fb7ac05e69', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$2. óra: Játékok$q$, $q$Játékszabályok, stratégiák, logikai gondolkodás páros és csoportmunkában.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év eleji ismétlés, diagnosztika$q$, $q$[{"id": "f4401ccf-1eb0-44d9-acba-c25adb27bcb8", "text": "Mi a stratégiai játékok lényege?", "type": "multiple-choice", "options": [{"id": "612ad0a1-9ddf-47f6-8f6e-bd8b5e08a55b", "text": "Előre megtervezett lépésekkel a cél elérése", "isCorrect": true}, {"id": "6e9d2d91-3cb8-4437-a19c-efe5d7651d1d", "text": "Kizárólag a szerencsére hagyatkozás", "isCorrect": false}, {"id": "29cd356f-7808-45d6-b0f3-e560f94eef4f", "text": "Kockadobás számolás nélkül", "isCorrect": false}, {"id": "f0651646-95b8-459d-bcdc-26ba1f1a263e", "text": "A szabályok figyelmen kívül hagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "e40d5821-942a-45a6-8411-c7fb3ec68369", "text": "A páros és csoportmunka során fontos a csapattársak véleményének meghallgatása.", "type": "true-false", "options": [{"id": "16bc546f-326b-444b-9bff-ffb431cf3e0e", "text": "Igaz", "isCorrect": true}, {"id": "33d0719f-b342-44aa-a4cf-b3714c53a514", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a6e3899e-37ec-4b74-9ad3-8dd0604b17f4", "text": "Hány mezőből áll egy klasszikus 8x8-as sakktábla?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "7c77ded4-9811-4131-b8a7-f944c2799dff", "text": "Melyik játék fejleszti kifejezetten a logikai gondolkodást és a számolást?", "type": "multiple-choice", "options": [{"id": "9cff0be9-ce75-4890-8702-63fdc9ad6b13", "text": "Sudoku", "isCorrect": true}, {"id": "f4f893a5-d9b1-4fdd-bfb2-154638db7877", "text": "Fócsoport", "isCorrect": false}, {"id": "b71c8873-0787-4fed-a4e5-4f7ded150d83", "text": "Futóverseny", "isCorrect": false}, {"id": "bdab939c-8f25-4d54-8d10-5359bd522324", "text": "Kő-papír-olló", "isCorrect": false}], "timeLimit": 15}, {"id": "240d7433-42a6-40e4-9b21-e524793be1c0", "text": "A bűvös négyzetben minden sor, oszlop és átló összege megegyezik.", "type": "true-false", "options": [{"id": "4260f4b7-0779-4963-a437-5826c81c9a15", "text": "Igaz", "isCorrect": true}, {"id": "a26f3e89-b717-4cdc-a1e6-4d62d0afbbf7", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3f5fa50a-26b5-4f75-9e78-063c5810a1a7", "text": "Mennyi az 1, 2, 3, 4, 5 számok összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "ca2de4a0-ebf7-4819-8a55-dde9f07eef67", "text": "A szabályok betartása elengedhetetlen a fair play játékban.", "type": "true-false", "options": [{"id": "2c908fdd-7955-4c4e-b20d-70bb08fe6b83", "text": "Igaz", "isCorrect": true}, {"id": "5e1e0db7-c7eb-4367-9308-d16ddc9ff5b4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('d6838359-10dc-48c4-8a2e-d4a6b75449d0', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$3. óra: Év eleji diagnosztikus felmérés$q$, $q$Az 5. osztályban tanult ismeretek felmérése, tudásszint diagnosztizálása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Év eleji ismétlés, diagnosztika$q$, $q$[{"id": "391d4d34-c615-4c74-b8f9-019d398348c7", "text": "1. Mennyi (-12) + 5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "bcdf5513-3d2d-41b0-8e75-ca758eeb6d4a", "text": "2. Mennyi 3/4 + 1/4?", "type": "multiple-choice", "options": [{"id": "603ba6f0-f5d4-4b49-9162-f80ce641f743", "text": "1 egész (4/4)", "isCorrect": true}, {"id": "028625c6-a437-44be-b88d-92c72c824b3a", "text": "2/4", "isCorrect": false}, {"id": "9e02dd7f-c2a5-4ada-be12-fd0964a4250c", "text": "4/8", "isCorrect": false}, {"id": "175e368c-797e-4902-93c3-c5aac5aa5e00", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "01b286bf-f186-4e9c-9c1a-0c40b688d1ae", "text": "3. Mennyi a 4 cm oldalú négyzet kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "7f095152-1aed-4105-ac81-119eee9bb9d5", "text": "4. Mennyi a 4 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "c9f64138-8e60-4a88-9d99-6736ae652918", "text": "5. Hány gramm 2,5 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "f0ce0147-618a-4220-b416-27297ba93381", "text": "6. A negatív számok a nullától balra találhatók a számegyenesen.", "type": "true-false", "options": [{"id": "0f28cd50-8965-4e4f-8171-6e16db4b26f9", "text": "Igaz", "isCorrect": true}, {"id": "6f623e83-a2ba-447b-87ef-5cc697a644b1", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f9ca7815-574b-43ec-82e7-90233ec891c6", "text": "7. Hány perc 1 és fél óra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "7472a84d-60e3-4f00-9b18-689254b87a4b", "text": "8. Mennyi 0,5 + 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "2a61ffc3-8095-4ddc-980b-6d6bb369f636", "text": "9. A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "50bb89c7-7489-470f-9468-08fa84bc8c4b", "text": "Igaz", "isCorrect": true}, {"id": "d6bd493f-2c88-4dbd-bfdf-4a7152b6a9be", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "43642473-c4f2-45ee-a331-9fc64c8826c9", "text": "10. Hány csúcsa van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('43f89836-2079-4e28-b6b0-314f03bbf0f6', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$4. óra: Műveletek az egész számok körében$q$, $q$Mit tanultunk ötödik osztályban? A felmérés tapasztalatainak feldolgozása, hibajavítás.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "d59ac4b4-d146-4442-bfb9-af4e03d1ad83", "text": "Mennyi (-8) + (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "b1207a9d-9895-4d19-a358-d9b0961cc15a", "text": "Mennyi (-6) - (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "d7b467a3-9e0a-43f6-a854-c759fa083da2", "text": "Az ellentett számok összege mindig 0.", "type": "true-false", "options": [{"id": "cca4751b-9c5d-4c09-ba8d-7efe9fd69c21", "text": "Igaz", "isCorrect": true}, {"id": "b447135d-518b-4aee-82b8-18d3328379a9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ddd10be7-b325-4422-9f7a-aa5a50215789", "text": "Mennyi |-25| (a -25 abszolút értéke)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "25e14920-f709-441c-9471-6947dca8040f", "text": "Melyik szám nagyobb: -15 vagy -8?", "type": "multiple-choice", "options": [{"id": "31628308-f58d-4ebb-bcb9-549a77151933", "text": "-8", "isCorrect": true}, {"id": "63dd3878-bb2b-4cb7-a832-8d37667bc0e1", "text": "-15", "isCorrect": false}, {"id": "45217bc6-76ff-433a-81de-e93e0275e2bd", "text": "Egyenlőek", "isCorrect": false}, {"id": "a61f68bf-6cc2-46c2-a7d6-eb7aba2be1c7", "text": "Nem összehasonlítható", "isCorrect": false}], "timeLimit": 15}, {"id": "1fb665f4-f457-4d0a-88dc-5152d5ef139c", "text": "A nullánál kisebb számokat negatív számoknak nevezzük.", "type": "true-false", "options": [{"id": "10900d3d-4a81-473d-84f1-41e9a71f90d4", "text": "Igaz", "isCorrect": true}, {"id": "86fff44f-d2e6-4d81-8fb8-