INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ce8cc868-6d76-45f4-9e9e-6e3beb228148', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$5. óra: Az egész számok szorzása$q$, $q$Negatív számokkal való szorzás, az előjelszabály megértése és alkalmazása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "e788d750-df7d-4eab-a665-33f858723cf2", "text": "Mi az előjelszabály két negatív szám szorzásakor? (- * -)", "type": "multiple-choice", "options": [{"id": "2a5574d9-d03b-4050-a4fa-64ae6d112c2d", "text": "Pozitív (+)", "isCorrect": true}, {"id": "a19d4681-30ee-44c2-9c45-172ff1314366", "text": "Negatív (-)", "isCorrect": false}, {"id": "3c1f97e9-2dcc-469c-aaea-1c661b871f13", "text": "Mindig 0", "isCorrect": false}, {"id": "3266316e-7a1f-45f0-829e-172df7fc90ec", "text": "Nem lehet megszorozni", "isCorrect": false}], "timeLimit": 15}, {"id": "2dcd0bc7-d916-4b16-8f9b-b281650a6287", "text": "Mennyi (-4) * (+5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-20"}, {"id": "b9762de6-c748-4cb8-bd78-99ab0c5e614a", "text": "Mennyi (-6) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "42"}, {"id": "d87f5577-0436-4639-81ef-f294bdc5d1d3", "text": "Egy pozitív és egy negatív szám szorzata mindig negatív.", "type": "true-false", "options": [{"id": "4964d003-0cd6-416c-bc54-d78290cda62e", "text": "Igaz", "isCorrect": true}, {"id": "09b4d34e-bc5d-4380-af9d-b78d74c48989", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "47dacad7-2cce-4ea8-9ecb-e893623d42aa", "text": "Mennyi (-3) * 0?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}, {"id": "62e47042-f0ad-4474-8744-50cb1bea57ee", "text": "Ha három negatív számot szorzunk össze, a szorzat előjele negatív lesz.", "type": "true-false", "options": [{"id": "7292b793-666a-4fba-8658-a50012b1cd23", "text": "Igaz (- * - * - = -)", "isCorrect": true}, {"id": "a72b7e13-e7f2-4012-b232-904f8bd278e4", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2e693d7b-c0a8-4fb8-ad16-4139ed334a30", "text": "Mennyi (-2) * (-3) * (-4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-24"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('24273287-ab03-4bb8-9429-89cf07b3f88d', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$6. óra: Gyakorlóóra: az egész számok szorzása$q$, $q$Több tényező előjelének meghatározása, szorzások gyakorlása.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "804342f4-fc4a-4ae7-b680-c09595ad6c9f", "text": "Mennyi (-5) * (-2) * (+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "e3c9870c-f9fb-4155-a558-cce907d05426", "text": "Ha egy szorzatban páros számú negatív tényező van, a szorzat előjele:", "type": "multiple-choice", "options": [{"id": "818d2cd6-9547-4dd3-851d-6c2c856bafec", "text": "Pozitív", "isCorrect": true}, {"id": "531b6afb-ffba-4c5e-835d-3e29de20d69a", "text": "Negatív", "isCorrect": false}, {"id": "58d55b3e-885b-48ad-8f76-bb168e63ae8d", "text": "Nulla", "isCorrect": false}, {"id": "fcd1bb4f-021b-4d6d-922a-f27727ed4587", "text": "Változó", "isCorrect": false}], "timeLimit": 15}, {"id": "f0eb03fe-74c0-4d60-9eaf-81156e0e44fd", "text": "Mennyi (-10) * (-10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "e704049f-2edf-437a-b1ff-5045ea257d6b", "text": "A 0-val való szorzás eredménye mindig 0.", "type": "true-false", "options": [{"id": "8dd02eb9-fc6e-4d29-b51f-6c572a21e7df", "text": "Igaz", "isCorrect": true}, {"id": "a8d4c647-07dc-4b52-93d7-f110e1dd2fc6", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "46b8f549-fef6-457e-8949-5c172a234006", "text": "Mennyi (-1) * (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}, {"id": "7771a253-ad47-4295-a75c-a5d6426cd7c4", "text": "Mennyi a (-2) köbe ( (-2) * (-2) * (-2) )?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-8"}, {"id": "cf23c57e-df0c-4e47-a6e0-b44ba8450ba8", "text": "Az írásbeli szorzáskor az előjelet a művelet végzésétől függetlenül, az előjelszabály szerint állapítjuk meg.", "type": "true-false", "options": [{"id": "976265aa-4f62-461e-9eac-1cd6f73d2e05", "text": "Igaz", "isCorrect": true}, {"id": "26ce7cdf-deaf-47dd-91ab-e40f396f349a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('13078bd2-3a86-4ee0-9417-8964837183c1', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$7. óra: Az egész számok osztása$q$, $q$Negatív osztandó, osztóval végzett műveletek algoritmusa, előjelszabály osztásnál.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "863c2e62-8111-4a56-8f36-fa945381843f", "text": "Mi az előjelszabály egész számok osztásakor?", "type": "multiple-choice", "options": [{"id": "ba348741-d00c-4c64-a866-26c0be8a46ba", "text": "Ugyanaz, mint a szorzásnál (+:+=+, -:-=+, +:-=-, -:+=-)", "isCorrect": true}, {"id": "8513c2fe-f7c8-4254-81df-228dfd429ae3", "text": "Mindig negatív", "isCorrect": false}, {"id": "0c5654f3-617a-4914-9dbb-5edbc44351af", "text": "Mindig pozitív", "isCorrect": false}, {"id": "7a3b3fa2-d30f-4b2a-931b-6f12c4d4c901", "text": "Kivonást kell végezni", "isCorrect": false}], "timeLimit": 15}, {"id": "f8dff6b9-8899-4fdd-9420-3415e48ec3da", "text": "Mennyi (-20) : (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "d39f83ce-4599-47fd-bd28-a36702c6521b", "text": "Mennyi (-36) : (-6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "58f8fc5c-5050-4d00-8c96-497c64d75e3c", "text": "Nullával osztani nem lehet a matematikában.", "type": "true-false", "options": [{"id": "82433fdc-1ffd-40b4-9549-e22b2a21a267", "text": "Igaz", "isCorrect": true}, {"id": "41a0e522-5ab6-4680-9adf-3cfc6feba800", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "82e117f8-bb12-4053-b069-0ba3dda75b2a", "text": "Mennyi (+50) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "2074c604-5e57-4fcd-a9e4-940d8553b473", "text": "Ha a (-15)-öt elosztjuk (-3)-mal, az eredmény pozitív szám.", "type": "true-false", "options": [{"id": "90465b21-6035-4715-81a9-6d08b3c470d3", "text": "Igaz", "isCorrect": true}, {"id": "22976000-4b1b-47a6-adf3-23144732e391", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f9c2e7c1-57b6-4c7a-b20b-2e7f869922e2", "text": "Mennyi 0 : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('ea2d282e-4d39-40ee-b629-d41f0dc45ebb', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$8. óra: Az egész számok osztásának gyakorlása$q$, $q$Írásbeli és fejben osztás gyakorlása negatív és pozitív számokkal.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "1a254efe-9a4e-4cbd-a0e6-e842510272e3", "text": "Mennyi (-100) : (-25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "3b397160-c36e-41ab-bf81-b3cd79044def", "text": "Mennyi (-48) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "e4fee0d4-a3e2-4a0f-b2c7-d558f570b0a0", "text": "Melyik egyenlet helyes?", "type": "multiple-choice", "options": [{"id": "9276dc22-2182-4eac-8a76-92303d31abe8", "text": "(-18) : (-3) = 6", "isCorrect": true}, {"id": "61055e14-5b2b-4eba-9a66-78f14fef954c", "text": "(-18) : (-3) = -6", "isCorrect": false}, {"id": "2ed410e9-c5e3-44ff-a5dd-e2b4bd392356", "text": "(-18) : (+3) = 6", "isCorrect": false}, {"id": "c5e0e349-17e1-4aa7-be74-9d769d019027", "text": "(+18) : (-3) = 6", "isCorrect": false}], "timeLimit": 15}, {"id": "06c6227b-3379-479c-970e-a2f884ee675b", "text": "A hányados ellenőrzése szorzással történik.", "type": "true-false", "options": [{"id": "a5833163-a196-4b5e-a1a9-e31d111284f8", "text": "Igaz", "isCorrect": true}, {"id": "553a2b20-ad48-445b-b107-62bab2d51db9", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "1cb987fc-5211-4fce-aced-0d4ef3e69f06", "text": "Mennyi (-81) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "51926bd1-e440-457a-bac8-3ddb6978b9b0", "text": "Ha két szám hányadosa pozitív, a két szám előjele azonos.", "type": "true-false", "options": [{"id": "6242fe37-8b48-4c64-90e1-2d2586829786", "text": "Igaz", "isCorrect": true}, {"id": "9609d633-9761-41e7-b2a5-10d227445c3a", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "551cc081-4555-466c-b297-44c221107903", "text": "Mennyi (-144) : (-12)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('03ca345f-28bd-4731-9d58-8536376c62f5', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$9. óra: Hány eset van? Számoljuk össze!$q$, $q$Összeszámlálás fagráffal (ágrajz), táblázattal, rendszerezett felsorolással.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "beb36227-59d8-4a40-b772-714abb837279", "text": "Milyen eszközt használhatunk az összes lehetőség rendszerezett szemléltetésére?", "type": "multiple-choice", "options": [{"id": "90d97a74-3faf-4026-b70e-e42797b69534", "text": "Fagráfot (ágrajzot) és táblázatot", "isCorrect": true}, {"id": "f0a39196-53f8-4ae6-99db-e0beb81f2f35", "text": "Szögmérőt", "isCorrect": false}, {"id": "889a3b7c-bab1-4929-bfdd-3d9714af1d43", "text": "Körzőt", "isCorrect": false}, {"id": "1e20615e-ed9b-4a55-856d-bff1e237f05a", "text": "Vonalzót", "isCorrect": false}], "timeLimit": 15}, {"id": "363dd606-33aa-4138-b167-5e0a79b42cc4", "text": "Hányféleképpen ülhet le 2 gyerek (Peti és Kati) két egymás melletti székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "aaceefb5-7114-4a19-aa3c-d4826a1d1be7", "text": "Hány különböző 2 jegyű szám képezhető az 1 és 2 számjegyekből (számjegyismétléssel)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "a50fbc27-192e-4404-84cf-c58860085ccf", "text": "A rendszerezett felsorolás segít abban, hogy egyetlen lehetőséget se hagyjunk ki.", "type": "true-false", "options": [{"id": "bf5c8e6b-9728-46f9-ae41-7ba850fb2a32", "text": "Igaz", "isCorrect": true}, {"id": "5d41e19e-41b4-4e1a-b441-a6548d51bc22", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "29402f97-ab8c-4043-bcce-a13d7990f0dd", "text": "Hányféleképpen választhatunk ki 3 póló és 2 nadrág közül egy ruhakészletet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "00b44267-d75c-4b54-aabd-369e83f071dc", "text": "A kombinatorikai feladatoknál a sorrend mindig számít.", "type": "true-false", "options": [{"id": "e98ff662-f3eb-4c9a-a721-cc727083ae19", "text": "Igaz", "isCorrect": false}, {"id": "e47d49b2-2e1f-4aff-9e9b-ba759297c516", "text": "Hamis (van ahol számít, van ahol nem)", "isCorrect": true}], "timeLimit": 15}, {"id": "7014af35-b7e1-45a8-8eaa-e01a95a5aa6d", "text": "Hány lapja van egy érmének (kimenetelek száma)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES ('174c7d3d-6f7c-46fe-b1de-e116b0b0b7ec', '21feff02-016d-46e2-bb9d-c27495133b1b', $q$10. óra: Gyakorlóóra. Hány eset van? Számoljuk össze!$q$, $q$Összeszámlálási feladatok gyakorlása fagráffal és táblázattal.$q$, $q$Matematika$q$, $q$6. osztály$q$, $q$Egész számok, oszthatóság$q$, $q$[{"id": "3f986d72-80a4-44f4-b7ea-76552e32520a", "text": "Hány 2 jegyű páros szám képezhető az 1, 2, 3 számjegyekből (számjegyismétlés nélkül)?", "type": "multiple-choice", "options": [{"id": "f8175462-e1e2-44a2-9812-79073f8910f3", "text": "2 (12, 32)", "isCorrect": true}, {"id": "84d2987e-dcde-42e1-8a1f-6b8d74280e4c", "text": "3", "isCorrect": false}, {"id": "783af1c9-ac2e-4f2c-b928-b43b2cc00606", "text": "4", "isCorrect": false}, {"id": "131682e3-765a-4091-801a-df4ea9081549", "text": "6", "isCorrect": false}], "timeLimit": 15}, {"id": "f9384c95-a9c9-4ede-92c2-d397150f78de", "text": "Három barát köszöntésekor (mindenki mindenkivel kezet fog) hány kézfogás történik?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "3"}, {"id": "46a4a6ad-6756-476c-b210-0777b779a1ff", "text": "A fagráf ágai az egyes döntési lépéseket ábrázolják.", "type": "true-false", "options": [{"id": "f5e7f327-b47e-40f6-bff4-0000f1934aee", "text": "Igaz", "isCorrect": true}, {"id": "a897c586-b127-48b3-87e2-41f779d50846", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "5f9d02ac-e0fb-4c40-8965-42748ecf7bff", "text": "Hány különböző sorrendben futhat be a célba 3 versenyző (A, B, C)? (3! = 3*2*1)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "1dd6001a-6820-4bdd-a8c5-120046d53762", "text": "Ha 4 csapat játszik körmérkőzést (mindenki mindenkivel egyszer), hány mérkőzést játszanak összesen?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "3e20e2ad-8829-436f-8e3d-d83caa8a1e25", "text": "Egy szabályos dobókocka eldobásakor 6-féle kimenetel lehetséges.", "type": "true-false", "options": [{"id": "e185f4ae-1ca9-4fc7-995e-04177cbd983d", "text": "Igaz", "isCorrect": true}, {"id": "08372506-c7af-4c03-800e-f2f2640e8315", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "63eff87c-5713-470e-8521-63488a73f13f", "text": "Hány kétjegyű szám képezhető a 0 és 5 számjegyekből (0 nem lehet az első számjegy)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]$q$::jsonb, true, NOW()) ON CONFLICT (id) DO NOTHING;